#!/usr/bin/env python3
r"""
Protein Painter - desktop app version (Flask)
=============================================
Same interface as the standalone HTML tool, plus ONE added capability:
custom color schemes are saved permanently to a file on this machine, so
they persist across sessions.

SETUP (one time):
    pip install flask

RUN:
    python protein_painter_app.py
Then open the address it prints (default http://127.0.0.1:5000) in a browser.
The app tries to open your browser automatically.

Custom schemes are stored in a single JSON file in your user config dir:
    - Windows: %APPDATA%\ProteinPainter\schemes.json
    - macOS:   ~/Library/Application Support/ProteinPainter/schemes.json
    - Linux:   ~/.config/ProteinPainter/schemes.json
Delete that file to wipe all saved schemes.
"""
import base64, json, os, sys, threading, webbrowser
from pathlib import Path

try:
    from flask import Flask, Response, request, jsonify
except ImportError:
    sys.exit("Flask is not installed. Run:  pip install flask")

# ---- where the scheme library lives ----
def config_dir() -> Path:
    if sys.platform.startswith("win"):
        base = Path(os.environ.get("APPDATA", Path.home() / "AppData" / "Roaming"))
    elif sys.platform == "darwin":
        base = Path.home() / "Library" / "Application Support"
    else:
        base = Path(os.environ.get("XDG_CONFIG_HOME", Path.home() / ".config"))
    d = base / "ProteinPainter"
    d.mkdir(parents=True, exist_ok=True)
    return d

SCHEMES_FILE = config_dir() / "schemes.json"

def read_schemes() -> dict:
    if not SCHEMES_FILE.exists():
        return {}
    try:
        data = json.loads(SCHEMES_FILE.read_text(encoding="utf-8"))
        # expect {name: [hex, ...]}
        return {k: v for k, v in data.items() if isinstance(v, list)}
    except Exception:
        return {}

def write_schemes(d: dict) -> None:
    SCHEMES_FILE.write_text(json.dumps(d, indent=2), encoding="utf-8")

# The interface HTML is stored base64-encoded so it can't collide with Python
# string syntax (no backslash/quote escaping headaches). Decoded once at startup.
_HTML_B64 = ""
INDEX_HTML = base64.b64decode(_HTML_B64).decode("utf-8")

app = Flask(__name__)

@app.route("/")
def index():
    return Response(INDEX_HTML, mimetype="text/html")

@app.route("/api/schemes", methods=["GET"])
def get_schemes():
    return jsonify(read_schemes())

@app.route("/api/schemes/<name>", methods=["PUT"])
def put_scheme(name):
    body = request.get_json(silent=True) or {}
    colors = body.get("colors")
    if not isinstance(colors, list) or not all(isinstance(c, str) for c in colors):
        return jsonify({"error": "colors must be a list of hex strings"}), 400
    schemes = read_schemes()
    schemes[name] = colors
    write_schemes(schemes)
    return jsonify({"ok": True, "name": name, "count": len(colors)})

@app.route("/api/schemes/<name>", methods=["DELETE"])
def delete_scheme(name):
    schemes = read_schemes()
    if name in schemes:
        del schemes[name]
        write_schemes(schemes)
    return jsonify({"ok": True})

def main():
    host, port = "127.0.0.1", 5000
    url = f"http://{host}:{port}"
    print(f"Protein Painter running at {url}")
    print(f"Saved schemes: {SCHEMES_FILE}")
    print("Press Ctrl+C to stop.")
    # open the browser shortly after the server starts
    threading.Timer(0.8, lambda: webbrowser.open(url)).start()
    app.run(host=host, port=port, debug=False)

if __name__ == "__main__":
    main()
